mapper.select:
with lag_date as ( select date_sub(sd, interval abs(DATEDIFF(sd, ed)) day) psd, date_sub(sd, interval 1 day) ped, sd, ed from ( select #{model.startTime} as sd , #{model.endTime} as ed) y ) select id, tag_type, tag_id, tag_category, current_frequency, allocation_status, format(((cp - pp) / cp) * 100, 2 ) as seq, /** 环比 **/ client_id, channel_source, word_name from ( select c1.count_ as cp, /** 本周期 **/ ifnull(c2.count_, 0 ) as pp, /** 上周期 **/ c4.id as id, c4.tag_id, c4.tag_type, c4.tag_category, c4.current_frequency, c4.allocation_status, c1.client_id, c1.channel_source, c1.word_name from ( select if(sum(current_frequency) is null, 0, sum(current_frequency)) count_, client_id, channel_source, word_name, max(update_time) as update_time, max(create_time) as create_time from cli_high_frequency_words, lag_date l where create_time between l.sd and l.ed
and allocation_status = #{model.allocationStatus}
and tag_type = #{model.tagType}
and word_name like concat('%',#{model.name},'%')
group by client_id, channel_source, word_name order by update_time desc )c1 left join ( select if(sum(current_frequency) is null, 0, sum(current_frequency)) count_, client_id, channel_source, word_name from cli_high_frequency_words, lag_date l where create_time between l.psd and l.ped
and allocation_status = #{model.allocationStatus}
and tag_type = #{model.tagType}
and word_name like concat('%',#{model.name},'%')
group by client_id, channel_source, word_name )c2 on c1.client_id = c2.client_id and c1.channel_source = c2.channel_source and c1.word_name = c2.word_name left join ( select id, tag_type, tag_id, tag_category, current_frequency, allocation_status, client_id, channel_source, word_name, update_time, create_time from cli_high_frequency_words, lag_date l where create_time between l.sd and l.ed
and allocation_status = #{model.allocationStatus}
and tag_type = #{model.tagType}
and word_name like concat('%',#{model.name},'%')
)c4 on c1.client_id = c4.client_id and c1.channel_source = c4.channel_source and c1.word_name = c4.word_name and c1.update_time = c4.update_time and c1.create_time = c4.create_time ) a

select if(sum(current_frequency) is null,
          0,
          sum(current_frequency)) historyTotalFrequency
from cli_high_frequency_words
where word_name = #{wordName}
  and client_id = #{clientId}
  and channel_source = #{channelSource}
group by client_id,
         channel_source,
         word_name
